import{_ as o,o as d,c,an as a}from"./chunks/framework.DJIkLx_7.js";const u=JSON.parse('{"title":"Binary Operations","description":"","frontmatter":{},"headers":[],"relativePath":"api_binary.md","filePath":"api_binary.md","lastUpdated":null}'),i={name:"api_binary.md"};function t(r,e,n,l,s,p){return d(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="Binary-Operations" tabindex="-1">Binary Operations <a class="header-anchor" href="#Binary-Operations" aria-label="Permalink to &quot;Binary Operations {#Binary-Operations}&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">Prefer `@.` for multi-op elementwise expressions so every operator is dotted. Missing a dot silently changes the meaning and can prevent broadcast fusion. See [Kernel Fusion](perf/kernel_fusion.md).</p><p></p></div><p>The following binary operations are supported and can be applied elementwise to pairs of <code>NDArray</code> values:</p><ul><li><code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>, <code>^</code>, <code>%</code>, <code>&lt;</code>, <code>&lt;=</code>, <code>&gt;</code>, <code>&gt;=</code>, <code>==</code>, <code>!=</code>, <code>&amp;</code>, <code>|</code>, <code>⊻</code>, <code>&lt;&lt;</code>, <code>&gt;&gt;</code>, <code>atan</code>, <code>hypot</code>, <code>max</code>, <code>min</code>, <code>lcm</code>, <code>gcd</code>, <code>fld</code>, <code>mod</code>, <code>rem</code>, <code>copysign</code></li></ul><h2 id="Differences-from-Base-Julia" tabindex="-1">Differences from Base Julia <a class="header-anchor" href="#Differences-from-Base-Julia" aria-label="Permalink to &quot;Differences from Base Julia {#Differences-from-Base-Julia}&quot;">​</a></h2><ul><li><p><code>div</code> / <code>÷</code> are not provided. cuPyNumeric floor-divide matches Julia <code>fld</code> (toward <code>-Inf</code>), not truncated <code>div</code>. For example <code>-7 ÷ 2</code> is <code>-3</code> in Julia and <code>-4</code> for <code>fld</code>.</p></li><li><p><code>&amp;</code>, <code>|</code>, <code>⊻</code> are integer and <code>Bool</code> bitwise ops. <code>&lt;&lt;</code> and <code>&gt;&gt;</code> are integers excluding <code>Bool</code>.</p></li><li><p><code>copysign</code> is float-only.</p></li></ul>',6)])])}const m=o(i,[["render",t]]);export{u as __pageData,m as default};
